def solve(weights, values, capacity):
    """Return the maximum total value of items (0/1 knapsack) that fit in capacity."""
    dp = [0] * (capacity + 1)
    for w, v in zip(weights, values):
        if w <= capacity:
            for c in range(capacity, w - 1, -1):
                cand = dp[c - w] + v
                if cand > dp[c]:
                    dp[c] = cand
    return dp[capacity]

