def solve(meetings):
    """Return the maximum number of non-overlapping meetings (activity selection).

    Tolerates entries carrying extra fields, e.g. [start, end, label];
    only the first two numbers (start, end) are used.
    """
    intervals = []
    for m in meetings or []:
        try:
            start, end = m[0], m[1]
        except (TypeError, ValueError, IndexError):
            continue
        intervals.append((start, end))
    intervals.sort(key=lambda p: (p[1], p[0]))
    count = 0
    last_end = float("-inf")
    for start, end in intervals:
        if start >= last_end:
            count += 1
            last_end = end
    return count

def solve(coins, amount):
    """Return the fewest number of coins (unlimited supply) summing to amount, or -1."""
    if amount < 0:
        return -1
    INF = float("inf")
    dp = [0] + [INF] * amount
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a and dp[a - c] + 1 < dp[a]:
                dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

