def solve(coins, amount):
    if amount == 0:
        return 0
    if amount < 0 or coins is None:
        return -1
    good = [c for c in coins if isinstance(c, int) and c > 0]
    if not good:
        return -1
    INF = float('inf')
    dp = [0] + [INF] * amount
