def solve(n, b):
    """Convert integer n to base b (2 <= b <= 36) using digits 0-9 and a-z.
    Returns an empty string if b is outside the allowed range.
    """
    if not isinstance(b, int) or b < 2 or b > 36:
        return ''
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    sign = '-' if n < 0 else ''
    n = abs(n)
    res = []
    while n:
        n, rem = divmod(n, b)
        res.append(digits[rem])
    return sign + ''.join(reversed(res))

